'use client'
/**
 * lucide-react -> Phosphor shim (Redesign Brief §3). next.config aliases `lucide-react` to this file, so every
 * existing `import { Search } from 'lucide-react'` renders the Phosphor equivalent without touching 230 files.
 * Icons without a mapping fall straight through to real lucide. Sizing keeps lucide's 24px default; Tailwind
 * h-/w- classes still win. The active-state fill/duotone treatment lives in <Icon> (components/ui/Icon.tsx).
 * Generated by the redesign tooling; edit the map, not the output, when adding icons.
 */
