type P = Omit<SVGProps<SVGSVGElement>, 'ref'> & { size?: number | string; color?: string; strokeWidth?: number | string; absoluteStrokeWidth?: boolean }
// eslint-disable-next-line @typescript-eslint/no-explicit-any
function wrap(Glyph: ComponentType<any>, name: string) {
  const C = forwardRef<SVGSVGElement, P>(function ShimIcon({ size = 24, strokeWidth: _s, absoluteStrokeWidth: _a, ...rest }, ref) {
    return <Glyph ref={ref} size={size} weight="regular" {...rest} />
  })
  C.displayName = name
  return C
}

